PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('ADMIN','EDITOR','MODERATOR')), active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS refresh_tokens(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, revoked_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS scientific_sources(id INTEGER PRIMARY KEY, title TEXT NOT NULL, author TEXT NOT NULL DEFAULT '', year INTEGER NOT NULL DEFAULT 0, url TEXT NOT NULL, doi TEXT NOT NULL DEFAULT '', kind TEXT NOT NULL DEFAULT 'Relatório', description TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS species(id INTEGER PRIMARY KEY, common_name TEXT NOT NULL, scientific_name TEXT NOT NULL UNIQUE, image_url TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', physical_characteristics TEXT NOT NULL DEFAULT '', size TEXT NOT NULL DEFAULT '', diet TEXT NOT NULL DEFAULT '', habitat TEXT NOT NULL DEFAULT '', distribution TEXT NOT NULL DEFAULT '', brazil_presence TEXT NOT NULL DEFAULT 'Ocorrência a confirmar', northeast_presence TEXT NOT NULL DEFAULT 'Ocorrência a confirmar', ecology TEXT NOT NULL DEFAULT '', threats TEXT NOT NULL DEFAULT '', brazil_status TEXT NOT NULL DEFAULT 'Não verificado', iucn_status TEXT NOT NULL DEFAULT 'Não verificado', published INTEGER NOT NULL DEFAULT 1, archived INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS species_sources(species_id INTEGER NOT NULL REFERENCES species(id) ON DELETE CASCADE, source_id INTEGER NOT NULL REFERENCES scientific_sources(id) ON DELETE CASCADE, PRIMARY KEY(species_id,source_id));
CREATE TABLE IF NOT EXISTS indicators(id INTEGER PRIMARY KEY, title TEXT NOT NULL, value REAL NOT NULL, unit TEXT NOT NULL, year INTEGER NOT NULL, scope TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', source_id INTEGER REFERENCES scientific_sources(id), published INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS indicator_sources(indicator_id INTEGER NOT NULL REFERENCES indicators(id) ON DELETE CASCADE, source_id INTEGER NOT NULL REFERENCES scientific_sources(id) ON DELETE CASCADE, PRIMARY KEY(indicator_id,source_id));
CREATE TABLE IF NOT EXISTS institutions(id INTEGER PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', state TEXT NOT NULL DEFAULT '', city TEXT NOT NULL DEFAULT '', focus TEXT NOT NULL DEFAULT '', website TEXT NOT NULL DEFAULT '', image_url TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS observations(id INTEGER PRIMARY KEY, state TEXT NOT NULL, municipality TEXT NOT NULL, occurred_on TEXT NOT NULL, category TEXT NOT NULL CHECK(category IN ('AVISTAMENTO','ANIMAL_MORTO','CAPTURA_ACIDENTAL','POLUICAO','DEGRADACAO')), species TEXT NOT NULL DEFAULT '', description TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','UNDER_REVIEW','APPROVED','REJECTED')), internal_note TEXT NOT NULL DEFAULT '', rejection_reason TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_observations_status_state ON observations(status,state);
CREATE TABLE IF NOT EXISTS observation_history(id INTEGER PRIMARY KEY, observation_id INTEGER NOT NULL REFERENCES observations(id) ON DELETE CASCADE, actor_id INTEGER REFERENCES users(id), old_status TEXT NOT NULL, new_status TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS quiz_questions(id INTEGER PRIMARY KEY, prompt TEXT NOT NULL, explanation TEXT NOT NULL, published INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS quiz_options(id INTEGER PRIMARY KEY, question_id INTEGER NOT NULL REFERENCES quiz_questions(id) ON DELETE CASCADE, label TEXT NOT NULL, correct INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS audit_logs(id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id), action TEXT NOT NULL, entity TEXT NOT NULL, entity_id TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
